function claim() external whenNotPaused {
    _updatePool();
    _claimRewards(msg.sender);            // <-- mint + safeTransfer to user
    UserInfo storage user = userInfo[msg.sender];
    user.phUSDDebt = (user.amount * accPhUSDPerShare) / PRECISION;   // rebase AFTER
    user.stableDebt = (user.amount * accStablePerShare) / PRECISION; // rebase AFTER
}
